const dados = $input.first().json;

const workflow = dados.workflow?.name || 'Workflow desconhecido';
const erro = dados.execution?.error?.message
  || dados.trigger?.error?.message
  || 'Erro não identificado';

const no = dados.execution?.lastNodeExecuted || 'Não informado';

console.log(`[LM Gestão] Falha no workflow: ${workflow}`);
console.log(`Nó: ${no}`);
console.log(`Erro: ${erro}`);

return [{
  json: {
    workflow,
    no,
    erro,
    data: new Date().toISOString()
  }
}];
